 "content": "def transform(grid):
    """Replace interrupted portions of horizontal/vertical color runs with 2.

    For each color other than the dominant background, inspect its full rows and
    columns; within each line's first-to-last occurrence, recolor background gaps.
    """
    from collections import Counter
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r in range(h):
        positions = {}
        for c, value in enumerate(grid[r]):
            if value != background:
                positions.setdefault(value, []).append(c)
        for cols in positions.values():
            for left, right in zip(cols, cols[1:]):
                for c in range(left + 1, right):
                    if grid[r][c] == background:
                        out[r][c] = 2
    for c in range(w):
        positions = {}
        for r in range(h):
            value = grid[r][c]
            if value != background:
                positions.setdefault(value, []).append(r)
        for rows in positions.values():
            for top, bottom in zip(rows, rows[1:]):
                for r in range(top + 1, bottom):
                    if grid[r][c] == background:
                        out[r][c] = 2
    return out
